.exn_grid<-function(dimensions) {if(!length(dimensions))return(matrix(integer(),1,0));out<-as.matrix(expand.grid(lapply(rev(dimensions),function(d)0:(d-1L)),KEEP.OUT.ATTRS=FALSE,stringsAsFactors=FALSE));out[,rev(seq_len(ncol(out))),drop=FALSE]}
.exn_index<-function(grid,dimensions) {if(!length(dimensions))return(rep(1L,nrow(grid)));stride<-vapply(seq_along(dimensions),function(i)if(i==length(dimensions))1 else prod(dimensions[(i+1L):length(dimensions)]),numeric(1));as.vector(grid%*%stride)+1L}
.exn_logsum<-function(x) {maximum<-max(x);if(!is.finite(maximum))return(maximum);maximum+log(sum(exp(x-maximum)))}
compile_discrete_bayesian_network<-function(nodes,network_contract,elimination_order=NULL,max_factor_cells=1000000,context=NULL) {
 if(!is.list(nodes)||!length(nodes)||!is.null(names(nodes))) .cr_error('EXPERT_NETWORK','Nonempty node list required');ids<-.ex_ids(lapply(nodes,function(n)n$node_id),'node_ids');contract<-.ex_object(network_contract,'network_contract');target<-.ex_target(contract$target,context);limit<-.ex_integer(max_factor_cells,'max_factor_cells',10000000);if(limit==0L) .cr_error('EXPERT_NETWORK','Positive factor limit required')
 for(k in c('network_id','version','population_id','default_node','default_state')).cr_string(contract[[k]],k,'EXPERT_NETWORK');cutoff<-.cr_data_date(contract$known_at,'known_at');asof<-.cr_data_date(contract$as_of,'as_of');mapping<-setNames(nodes,ids)
 for(name in ids){node<-mapping[[name]];states<-.ex_ids(node$states,'states');parents<-.ex_ids(node$parents,'parents',TRUE);if(name%in%parents||length(setdiff(parents,ids))) .cr_error('EXPERT_NETWORK','Unknown or self parent');if(!(node$parameter_origin%in%c('ELICITED','ESTIMATED','FIXED'))) .cr_error('EXPERT_NETWORK','Parameter origin required');.cr_string(node$reference,'reference','EXPERT_NETWORK');if(.cr_data_date(node$known_at,'node known_at')>cutoff) .cr_error('EXPERT_LOOKAHEAD','CPT not available at knowledge cutoff');mapping[[name]]$states<-as.list(states);mapping[[name]]$parents<-as.list(parents)}
 topological<-character();remaining<-ids
 while(length(remaining)){eligible<-sort(remaining[vapply(remaining,function(i)all(unlist(mapping[[i]]$parents)%in%topological),logical(1))]);if(!length(eligible)) .cr_error('EXPERT_NETWORK_CYCLE','Directed network contains a cycle');topological<-c(topological,eligible);remaining<-setdiff(remaining,eligible)}
 for(name in topological){node<-mapping[[name]];parents<-unlist(node$parents);dimensions<-vapply(parents,function(p)length(mapping[[p]]$states),integer(1));size<-prod(dimensions)*length(node$states);if(size>limit) .cr_error('EXPERT_FACTOR_LIMIT','CPT exceeds factor-size limit');cpt<-node$cpt;if(!is.list(cpt)||length(cpt)!=prod(dimensions)) .cr_error('EXPERT_CPT','One CPT row per parent configuration required');indexed<-vector('list',prod(dimensions))
  for(row in cpt){given<-.ex_object(row$given,'given');if(!setequal(names(given),parents)||any(vapply(parents,function(p)!(given[[p]]%in%unlist(mapping[[p]]$states)),logical(1)))) .cr_error('EXPERT_CPT','Parent states do not match declared parents');key<-vapply(parents,function(p)match(given[[p]],unlist(mapping[[p]]$states))-1L,integer(1));index<-.exn_index(matrix(key,nrow=1),dimensions);probs<-.ex_vec(row$probabilities,'probabilities');if(!is.null(indexed[[index]])||length(probs)!=length(node$states)||any(probs<0)||abs(sum(probs)-1)>1e-12) .cr_error('EXPERT_CPT','Unique nonnegative CPT rows summing to one required');indexed[[index]]<-list(given=given,probabilities=as.list(probs))}
  node$cpt<-indexed;mapping[[name]]<-node
 }
 if(!(contract$default_node%in%ids)||!(contract$default_state%in%unlist(mapping[[contract$default_node]]$states))) .cr_error('EXPERT_NETWORK','Default node/state absent');order<-if(is.null(elimination_order))rev(topological)else .ex_ids(elimination_order,'elimination_order');if(!setequal(order,ids)) .cr_error('EXPERT_NETWORK','Elimination order must contain every node once')
 value<-.ex_seal(list(network_contract=contract,nodes=unname(mapping[topological]),topological_order=as.list(topological),elimination_order=as.list(order),max_factor_cells=limit),'network_hash')
 .cr_result(value,'expert.compile_discrete_bayesian_network','discrete_bayesian_network',context,limitations='CPTs are supplied, not estimated here. Parameter origins and knowledge dates remain explicit. Factorization assumes conditional independence; a directed graph alone establishes no causal interpretation.')
}

infer_discrete_credit_network<-function(compiled_network,evidence,query_node=NULL,context=NULL) {
 net<-.ex_read(compiled_network,'network_hash');contract<-net$network_contract;.ex_target(contract$target,context);ids<-vapply(net$nodes,function(n)n$node_id,character(1));nodes<-setNames(net$nodes,ids);evidence<-.ex_object(evidence,'evidence');query<-if(is.null(query_node))contract$default_node else query_node;limit<-net$max_factor_cells
 if(!(query%in%ids)||length(setdiff(names(evidence),ids))||any(vapply(names(evidence),function(n)!(evidence[[n]]%in%unlist(nodes[[n]]$states)),logical(1)))) .cr_error('EXPERT_NETWORK_EVIDENCE','Unknown query/evidence node or state')
 sizes<-vapply(nodes,function(n)length(n$states),integer(1));factors<-list();peak<-0
 for(name in ids){node<-nodes[[name]];scope<-c(unlist(node$parents),name);dimensions<-sizes[scope];grid<-.exn_grid(dimensions);values<-log(unlist(lapply(node$cpt,function(row)row$probabilities),use.names=FALSE));keep<-rep(TRUE,nrow(grid));for(n in intersect(scope,names(evidence)))keep<-keep&grid[,match(n,scope)]==match(evidence[[n]],unlist(nodes[[n]]$states))-1L;remaining<-setdiff(scope,names(evidence));factors[[length(factors)+1L]]<-list(scope=remaining,values=values[keep]);peak<-max(peak,sum(keep))}
 join<-function(group){scope<-unlist(net$topological_order);scope<-scope[scope%in%unique(unlist(lapply(group,function(f)f$scope)))];dimensions<-sizes[scope];cells<-prod(dimensions);if(cells>limit) .cr_error('EXPERT_FACTOR_LIMIT','Elimination intermediate exceeds frozen factor-size limit; use better order or explicit larger compile limit');peak<<-max(peak,cells);grid<-.exn_grid(dimensions);out<-rep(0,cells)
 for(f in group){subgrid<-grid[,match(f$scope,scope),drop=FALSE];index<-.exn_index(subgrid,sizes[f$scope]);out<-out+f$values[index]};list(scope=scope,values=out)}
 eliminated<-character()
 for(name in unlist(net$elimination_order)){if(name==query||name%in%names(evidence))next;selected<-vapply(factors,function(f)name%in%f$scope,logical(1));if(!any(selected))next;involved<-factors[selected];factors<-factors[!selected];joined<-join(involved);scope<-setdiff(joined$scope,name);grid<-.exn_grid(sizes[joined$scope]);index<-.exn_index(grid[,match(scope,joined$scope),drop=FALSE],sizes[scope]);values<-vapply(seq_len(prod(sizes[scope])),function(i).exn_logsum(joined$values[index==i]),numeric(1));factors[[length(factors)+1L]]<-list(scope=scope,values=values);eliminated<-c(eliminated,name)}
 joined<-join(factors);log_evidence<-.exn_logsum(joined$values);if(!is.finite(log_evidence)) .cr_error('EXPERT_IMPOSSIBLE_EVIDENCE','Evidence has probability zero under frozen network')
 if(query%in%names(evidence))posterior<-as.numeric(unlist(nodes[[query]]$states)==evidence[[query]])else{if(!identical(joined$scope,query)) .cr_error('NUMERICAL_FAILURE','Unexpected variables after elimination');posterior<-exp(joined$values-log_evidence)}
 probability<-exp(log_evidence);pd<-if(query==contract$default_node)posterior[match(contract$default_state,unlist(nodes[[query]]$states))]else NULL
 .cr_result(list(query_node=query,states=nodes[[query]]$states,posterior_probabilities=as.list(posterior),default_probability=pd,evidence=evidence,evidence_probability=probability,log_evidence_probability=log_evidence,evidence_probability_underflow=probability==0,eliminated_variables=as.list(eliminated),peak_factor_cells=peak,network_hash=net$network_hash,target=contract$target),'expert.infer_discrete_credit_network','probability_distribution',context,limitations='Exact finite factor elimination conditions on evidence and marginalizes unknown states. Evidence-probability underflow is flagged separately while finite log probability remains available.')
}
